1	// Regression coverage for a publish and a rollback contending for the same
2	// current version of one organization. Both operations accept or reject a
3	// change solely on the caller-supplied expected version, and only the winner
4	// may create a new version and a policy-change audit record. These tests pin
5	// that contract without assuming which side wins: the sequential tests pin
6	// each winner in turn by fixing the call order, and the concurrent test runs
7	// the real mutex race and judges whichever side actually succeeds by the
8	// same rules.
9	package darksafe
10	
11	import (
12		"errors"
13		"reflect"
14		"sync"
15		"testing"
16	)
17	
18	const contestOrg = "acme"
19	
20	// contentionFixture builds the three full policy sets involved in the race:
21	//
22	//   - v1 is the earlier published version: an explicit DENY for the probe,
23	//     carrying its own identifiable marker.
24	//   - v2 is the newer, current version: an ALLOW for the same subject,
25	//     action and resource with a different marker, so the two published
26	//     versions have genuinely different content and authorization results.
27	//   - candidate is the complete set the competing Publish submits: an ALLOW
28	//     with its own marker, distinct from every historical version.
29	//
30	// The rollback targets v1 and the publish submits candidate, so the two
31	// candidate modifications produce opposite authorization results for the
32	// same probe request (rollback denies, publish allows).
33	func contentionFixture() (v1, v2, candidate []Policy) {
34		v1 = []Policy{{
35			ID: "contest-v1-deny", Subject: "contest-subject", Action: "read",
36			Scope: "org/acme/ledger", Effect: EffectDeny,
37		}}
38		v2 = []Policy{{
39			ID: "contest-v2-allow", Subject: "contest-subject", Action: "read",
40			Scope: "org/acme/ledger", Effect: EffectAllow,
41		}}
42		candidate = []Policy{{
43			ID: "contest-publish-allow", Subject: "contest-subject", Action: "read",
44			Scope: "org/acme/ledger", Effect: EffectAllow,
45		}}
46		return
47	}
48	
49	// contestProbe is the access request used to tell the two candidate outcomes
50	// apart after the race.
51	func contestProbe() OrgRequest {
52		return request(contestOrg, "contest-subject", "contest-resource", "org/acme/ledger", "read")
53	}
54	
55	// setupContendedStore publishes v1 then v2, leaving the organization at
56	// current version 2 with two content-distinct historical versions.
57	func setupContendedStore(t *testing.T) (s *Store, v1, v2, candidate []Policy) {
58		t.Helper()
59		v1, v2, candidate = contentionFixture()
60		s = NewStore()
61		if v, err := s.Publish(contestOrg, 0, v1); err != nil || v != 1 {
62			t.Fatalf("publish v1 = %d, %v; want 1, nil", v, err)
63		}
64		if v, err := s.Publish(contestOrg, 1, v2); err != nil || v != 2 {
65			t.Fatalf("publish v2 = %d, %v; want 2, nil", v, err)
66		}
67		if got := s.CurrentVersion(contestOrg); got != 2 {
68			t.Fatalf("current version = %d, want 2 before contention", got)
69		}
70		// Document the fixture invariant: the two contending changes decide the
71		// probe differently, and the two existing versions differ as well.
72		probe := contestProbe()
73		if d := evaluate(probe, v1, 1); d.Allowed {
74			t.Fatalf("fixture: rollback target v1 must deny the probe, got %+v", d)
75		}
76		if d := evaluate(probe, candidate, 3); !d.Allowed {
77			t.Fatalf("fixture: publish candidate must allow the probe, got %+v", d)
78		}
79		if d := evaluate(probe, v2, 2); !d.Allowed {
80			t.Fatalf("fixture: current v2 must allow the probe, got %+v", d)
81		}
82		return s, v1, v2, candidate
83	}
84	
85	// checkContentionOutcome verifies the complete post-race contract for either
86	// winner. winner is "publish" (candidate became v3) or "rollback" (v1's
87	// content became v3).
88	func checkContentionOutcome(t *testing.T, s *Store, winner string, v1, v2, candidate []Policy) {
89		t.Helper()
90	
91		var wantPolicies []Policy
92		switch winner {
93		case "publish":
94			wantPolicies = candidate
95		case "rollback":
96			wantPolicies = v1
97		default:
98			t.Fatalf("unknown winner %q", winner)
99		}
100	
101		// Exactly one modification was accepted: the current version advanced by
102		// exactly one, and the losing request did not consume a version number.
103		if got := s.CurrentVersion(contestOrg); got != 3 {
104			t.Fatalf("[%s wins] current version = %d, want 3", winner, got)
105		}
106		if _, err := s.Policies(contestOrg, 4); !errors.Is(err, ErrVersionNotFound) {
107			t.Fatalf("[%s wins] version 4 exists (err=%v); the loser must not consume a version", winner, err)
108		}
109	
110		// The two pre-existing versions are fully intact and still queryable.
111		gotV1, err := s.Policies(contestOrg, 1)
112		if err != nil {
113			t.Fatalf("[%s wins] Policies(v1): %v", winner, err)
114		}
115		if !reflect.DeepEqual(gotV1, v1) {
116			t.Fatalf("[%s wins] v1 changed to %+v, want %+v", winner, gotV1, v1)
117		}
118		gotV2, err := s.Policies(contestOrg, 2)
119		if err != nil {
120			t.Fatalf("[%s wins] Policies(v2): %v", winner, err)
121		}
122		if !reflect.DeepEqual(gotV2, v2) {
123			t.Fatalf("[%s wins] v2 changed to %+v, want %+v", winner, gotV2, v2)
124		}
125	
126		// v3 holds exactly the winner's full policy set: no splicing of the two
127		// candidate sets, no partial loss, and no trace of the loser's content.
128		gotV3, err := s.Policies(contestOrg, 3)
129		if err != nil {
130			t.Fatalf("[%s wins] Policies(v3): %v", winner, err)
131		}
132		if !reflect.DeepEqual(gotV3, wantPolicies) {
133			t.Fatalf("[%s wins] v3 content = %+v, want exactly %+v", winner, gotV3, wantPolicies)
134		}
135	
136		// Relative to before the race, exactly ONE policy-change record exists,
137		// appended gaplessly, and its payload describes the successful operation
138		// only. The conflicting request left no record and no sequence gap.
139		recs := drainAudit(t, s, contestOrg, "", "")
140		if len(recs) != 3 {
141			t.Fatalf("[%s wins] audit records = %d, want 3", winner, len(recs))
142		}
143		for i, r := range recs {
144			if r.Seq != i+1 || r.Kind != AuditPolicyChange || r.Change == nil {
145				t.Fatalf("[%s wins] unexpected record at position %d: %+v", winner, i, r)
146			}
147		}
148		change := recs[2].Change
149		if change.Version != 3 {
150			t.Fatalf("[%s wins] new record names version %d, want 3 (rollback must not return the target version)", winner, change.Version)
151		}
152		if !reflect.DeepEqual(change.Policies, wantPolicies) {
153			t.Fatalf("[%s wins] audit policies = %+v, want %+v", winner, change.Policies, wantPolicies)
154		}
155		switch winner {
156		case "publish":
157			if change.RolledBack || change.SourceVersion != 0 {
158				t.Fatalf("[publish wins] change is tagged as a rollback: %+v", change)
159			}
160		case "rollback":
161			if !change.RolledBack || change.SourceVersion != 1 {
162				t.Fatalf("[rollback wins] change must name source v1: %+v", change)
163			}
164		}
165		// The complete exported chain, including the raced record, passes the
166		// existing offline verification.
167		exported, cp, err := s.AuditExport(contestOrg, 0)
168		if err != nil {
169			t.Fatalf("[%s wins] AuditExport: %v", winner, err)
170		}
171		if err := VerifyAudit(contestOrg, exported, cp); err != nil {
172			t.Fatalf("[%s wins] chain does not verify after contention: %v", winner, err)
173		}
174	
175		// A subsequent access request is decided by the new winning version, and
176		// the decision record persists the identical result.
177		probe := contestProbe()
178		wantDecision := evaluate(probe, wantPolicies, 3)
179		d := s.Decide(contestOrg, probe)
180		if !reflect.DeepEqual(d, wantDecision) {
181			t.Fatalf("[%s wins] Decide = %+v, want %+v from the new version", winner, d, wantDecision)
182		}
183		if d.Version != 3 {
184			t.Fatalf("[%s wins] decision used version %d, want 3", winner, d.Version)
185		}
186		decisions := drainAudit(t, s, contestOrg, AuditDecision, "")
187		if len(decisions) != 1 {
188			t.Fatalf("[%s wins] decision records = %d, want 1", winner, len(decisions))
189		}
190		dr := decisions[0]
191		if dr.Seq != 4 || !reflect.DeepEqual(dr.Decision.Decision, d) ||
192			!reflect.DeepEqual(dr.Decision.Request, probe) {
193			t.Fatalf("[%s wins] saved decision = %+v, want %+v for request %+v", winner, dr.Decision, d, probe)
194		}
195		rechecked, err := s.RecheckDecision(contestOrg, dr.Seq)
196		if err != nil {
197			t.Fatalf("[%s wins] RecheckDecision: %v", winner, err)
198		}
199		if !reflect.DeepEqual(rechecked, d) {
200			t.Fatalf("[%s wins] recheck = %+v, want %+v", winner, rechecked, d)
201		}
202	
203		// Historical versions still review independently and were not rewritten
204		// by the contention.
205		if d1 := s.Review(contestOrg, 1, probe); !reflect.DeepEqual(d1, evaluate(probe, v1, 1)) {
206			t.Fatalf("[%s wins] review v1 drifted: %+v", winner, d1)
207		}
208		if d2 := s.Review(contestOrg, 2, probe); !reflect.DeepEqual(d2, evaluate(probe, v2, 2)) {
209			t.Fatalf("[%s wins] review v2 drifted: %+v", winner, d2)
210		}
211	
212		// Final chain (change + decision) still verifies in full.
213		exported, cp, err = s.AuditExport(contestOrg, 0)
214		if err != nil {
215			t.Fatalf("[%s wins] final AuditExport: %v", winner, err)
216		}
217		if len(exported) != 4 {
218			t.Fatalf("[%s wins] final records = %d, want 4", winner, len(exported))
219		}
220		if err := VerifyAudit(contestOrg, exported, cp); err != nil {
221			t.Fatalf("[%s wins] final chain does not verify: %v", winner, err)
222		}
223	}
224	
225	// TestPublishBeatsRollbackOnSameExpectedVersion pins the publish-winning
226	// ordering: the publish runs first while both callers still claim current
227	// version 2; the following rollback must be rejected as a conflict.
228	func TestPublishBeatsRollbackOnSameExpectedVersion(t *testing.T) {
229		s, v1, v2, candidate := setupContendedStore(t)
230	
231		newVersion, err := s.Publish(contestOrg, 2, candidate)
232		if err != nil || newVersion != 3 {
233			t.Fatalf("publish = %d, %v; want 3, nil", newVersion, err)
234		}
235		if _, err := s.Rollback(contestOrg, 2, 1); !errors.Is(err, ErrVersionConflict) {
236			t.Fatalf("contending rollback err = %v, want ErrVersionConflict", err)
237		}
238	
239		checkContentionOutcome(t, s, "publish", v1, v2, candidate)
240	}
241	
242	// TestRollbackBeatsPublishOnSameExpectedVersion pins the rollback-winning
243	// ordering: the rollback runs first while both callers claim version 2; the
244	// following publish must be rejected as a conflict.
245	func TestRollbackBeatsPublishOnSameExpectedVersion(t *testing.T) {
246		s, v1, v2, candidate := setupContendedStore(t)
247	
248		newVersion, err := s.Rollback(contestOrg, 2, 1)
249		if err != nil || newVersion != 3 {
250			t.Fatalf("rollback = %d, %v; want new version 3, not target version 1", newVersion, err)
251		}
252		if _, err := s.Publish(contestOrg, 2, candidate); !errors.Is(err, ErrVersionConflict) {
253			t.Fatalf("contending publish err = %v, want ErrVersionConflict", err)
254		}
255	
256		checkContentionOutcome(t, s, "rollback", v1, v2, candidate)
257	}
258	
259	// TestConcurrentPublishRollbackSameVersionContention runs the two operations
260	// as a genuine concurrent race: both goroutines are released from one barrier
261	// while declaring the same expected current version. The mutex decides the
262	// winner; regardless of which side wins, exactly one change is accepted and
263	// the same outcome rules apply. The test never assumes a fixed winner.
264	func TestConcurrentPublishRollbackSameVersionContention(t *testing.T) {
265		const iterations = 100
266		seenPublishWin := false
267		seenRollbackWin := false
268		for iter := 0; iter < iterations; iter++ {
269			s, v1, v2, candidate := setupContendedStore(t)
270	
271			start := make(chan struct{})
272			type outcome struct {
273				op  string
274				v   int
275				err error
276			}
277			results := make(chan outcome, 2)
278			var wg sync.WaitGroup
279			wg.Add(2)
280			go func() {
281				defer wg.Done()
282				<-start
283				v, err := s.Publish(contestOrg, 2, candidate)
284				results <- outcome{"publish", v, err}
285			}()
286			go func() {
287				defer wg.Done()
288				<-start
289				v, err := s.Rollback(contestOrg, 2, 1)
290				results <- outcome{"rollback", v, err}
291			}()
292			close(start)
293			wg.Wait()
294			close(results)
295	
296			var winner string
297			wins, conflicts := 0, 0
298			for r := range results {
299				switch {
300				case r.err == nil:
301					wins++
302					winner = r.op
303					if r.v != 3 {
304						t.Fatalf("iter %d: %s returned version %d, want the new version 3", iter, r.op, r.v)
305					}
306				case errors.Is(r.err, ErrVersionConflict):
307					conflicts++
308				default:
309					t.Fatalf("iter %d: %s unexpected error %v", iter, r.op, r.err)
310				}
311			}
312			if wins != 1 || conflicts != 1 {
313				t.Fatalf("iter %d: wins=%d conflicts=%d, want exactly one of each", iter, wins, conflicts)
314			}
315			switch winner {
316			case "publish":
317				seenPublishWin = true
318			case "rollback":
319				seenRollbackWin = true
320			}
321			checkContentionOutcome(t, s, winner, v1, v2, candidate)
322		}
323		// Informational: report if scheduling let only one side ever win. The
324		// sequential tests above pin both outcomes regardless, so this is not a
325		// failure condition.
326		if !seenPublishWin || !seenRollbackWin {
327			t.Logf("scheduler observed only one winner across %d iterations (publish=%v, rollback=%v); both orderings remain covered by the sequential tests",
328				iterations, seenPublishWin, seenRollbackWin)
329		}
330	}
331

