268	// TestRollbackToEmptyVersionFailuresLeaveStateUntouched preserves the existing
269	// failure contract for an empty target: a missing historical version is
270	// ErrVersionNotFound, a stale expected current version is ErrVersionConflict
271	// (the empty target is not exempt from the expected-version check), and no
272	// failure moves the current version, changes policy content, or appends an
273	// audit record.
274	func TestRollbackToEmptyVersionFailuresLeaveStateUntouched(t *testing.T) {
275		for shape, emptyPolicies := range emptyRollbackShapes() {
276			t.Run(shape, func(t *testing.T) {
277				org := "acme-fail-" + shape
278				s, req, _ := buildEmptyRollbackStore(t, org, emptyPolicies)
279	
280				// Before any rollback: a stale expected version against the empty
281				// target conflicts, and must not consume version 3 or a seq.
282				if _, err := s.Rollback(org, 9, 1); !errors.Is(err, ErrVersionConflict) {
283					t.Fatalf("stale rollback before success err = %v, want ErrVersionConflict", err)
284				}
285				if got := s.CurrentVersion(org); got != 2 {
286					t.Fatalf("current = %d, want 2 after failed rollback", got)
287				}
288				if _, err := s.Policies(org, 3); !errors.Is(err, ErrVersionNotFound) {
289					t.Fatalf("v3 exists after failed rollback, err = %v", err)
290				}
291				preRecs, _, err := s.AuditExport(org, 0)
292				if err != nil || len(preRecs) != 3 {
293					t.Fatalf("records before rollback = %d, %v; want 3", len(preRecs), err)
294				}
295	
296				// The successful rollback then creates v3.
297				if v, err := s.Rollback(org, 2, 1); err != nil || v != 3 {
298					t.Fatalf("rollback = %d, %v; want 3, nil", v, err)
299				}
300	
301				// Snapshot the successful state; failed calls below must leave it
302				// bit-for-bit intact, including the audit chain's head fingerprint.
303				okRecs, okCP, err := s.AuditExport(org, 0)
304				if err != nil || len(okRecs) != 4 {
305					t.Fatalf("records after rollback = %d, %v; want 4", len(okRecs), err)
306				}
307	
308				// Empty target with a stale expected version: conflict, even though
309				// version 1 genuinely exists and its content is empty.
310				if _, err := s.Rollback(org, 2, 1); !errors.Is(err, ErrVersionConflict) {
311					t.Fatalf("stale expected version on empty target err = %v, want ErrVersionConflict", err)
312				}
313				if _, err := s.Rollback(org, 0, 1); !errors.Is(err, ErrVersionConflict) {
314					t.Fatalf("expected-version-zero rollback err = %v, want ErrVersionConflict", err)
315				}
316				// A target that has never existed in this organization is not
317				// found, empty content or otherwise.
318				if _, err := s.Rollback(org, 3, 42); !errors.Is(err, ErrVersionNotFound) {
319					t.Fatalf("missing target err = %v, want ErrVersionNotFound", err)
320				}
321	
322				if got := s.CurrentVersion(org); got != 3 {
323					t.Fatalf("current = %d, want 3 after failed rollbacks", got)
324				}
325				gotV3, err := s.Policies(org, 3)
326				if err != nil || len(gotV3) != 0 {
327					t.Fatalf("Policies(v3) = %+v, %v; want empty, nil", gotV3, err)
328				}
329				postRecs, postCP, err := s.AuditExport(org, 0)
330				if err != nil {
331					t.Fatalf("export after failures: %v", err)
332				}
333				if len(postRecs) != len(okRecs) {
334					t.Fatalf("records changed: %d before failures, %d after", len(okRecs), len(postRecs))
335				}
336				if postCP != okCP {
337					t.Fatalf("audit head changed after failed rollbacks: %s vs %s", okCP.Fingerprint, postCP.Fingerprint)
338				}
339				if err := VerifyAudit(org, postRecs, postCP); err != nil {
340					t.Fatalf("chain no longer verifies after failures: %v", err)
341				}
342				// The pre-rollback prefix is still the same records and still
343				// verifies under its own checkpoint.
344				prefixCP := Checkpoint{Org: org, EndSeq: 3, Fingerprint: postRecs[2].Fingerprint}
345				if err := VerifyAudit(org, postRecs[:3], prefixCP); err != nil {
346					t.Fatalf("historical prefix no longer verifies: %v", err)
347				}
348				if !reflect.DeepEqual(postRecs[:3], preRecs) {
349					t.Fatalf("pre-rollback records were altered by later failures")
350				}
351				// Decisions are still made by the empty new version.
352				wantDenial := Decision{
353					Allowed: false, Reason: "no matching allow policy",
354					Matched: []string{}, Version: 3,
355				}
356				if d := s.Decide(org, req); !reflect.DeepEqual(d, wantDenial) {
357					t.Fatalf("decision after failures = %+v, want %+v", d, wantDenial)
358				}
359			})
360		}
361	}
